// Generator 2 naming, frozen from v0.2.2. Keep the vocabulary, spelling checks, rotation and RNG unchanged.
// Only season species need this copy; fusion and Mythic names keep their separate current generator.
import type { Family, Rng } from '../types.ts'

function hash128(s: string): [number, number, number, number] {
  let h1 = 1779033703, h2 = 3144134277, h3 = 1013904242, h4 = 2773480762
  for (let i = 0; i < s.length; i++) {
    const k = s.charCodeAt(i)
    h1 = h2 ^ Math.imul(h1 ^ k, 597399067)
    h2 = h3 ^ Math.imul(h2 ^ k, 2869860233)
    h3 = h4 ^ Math.imul(h3 ^ k, 951274213)
    h4 = h1 ^ Math.imul(h4 ^ k, 2716044179)
  }
  h1 = Math.imul(h3 ^ (h1 >>> 18), 597399067)
  h2 = Math.imul(h4 ^ (h2 >>> 22), 2869860233)
  h3 = Math.imul(h1 ^ (h3 >>> 17), 951274213)
  h4 = Math.imul(h2 ^ (h4 >>> 19), 2716044179)
  h1 ^= h2 ^ h3 ^ h4
  h2 ^= h1; h3 ^= h1; h4 ^= h1
  return [h1 >>> 0, h2 >>> 0, h3 >>> 0, h4 >>> 0]
}

/** A uint32 hash of a string. */
function hashString(s: string): number {
  return hash128(s)[0]
}

/** sfc32 seeded from the 128-bit hash of `seed`; returns uniform floats in [0, 1). */
function rngFromSeed(seed: string | number): Rng {
  let [a, b, c, d] = hash128(String(seed))
  const next = (): number => {
    const t = (((a + b) | 0) + d) | 0
    d = (d + 1) | 0
    a = b ^ (b >>> 9)
    b = (c + (c << 3)) | 0
    c = (c << 21) | (c >>> 11)
    c = (c + t) | 0
    return (t >>> 0) / 4294967296
  }
  for (let i = 0; i < 12; i++) next()
  return next
}

/** A shuffled copy (Fisher-Yates). */
function shuffle<T>(rng: Rng, items: readonly T[]): T[] {
  const out = items.slice()
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1))
    const t = out[i]!
    out[i] = out[j]!
    out[j] = t
  }
  return out
}

type Stage = 1 | 2 | 3
type NameLine = [string, string, string]
type Shape = { syllables: readonly [number, number]; letters: readonly [number, number] }

/** Syllables and letters per stage (SPEC section 23). */
const STAGE_SHAPE: Record<Stage, Shape> = {
  1: { syllables: [2, 2], letters: [4, 8] },
  2: { syllables: [2, 3], letters: [5, 9] },
  3: { syllables: [3, 4], letters: [6, 11] },
}
/** Legendaries: stately two- or three-syllable compounds. */
const LEGENDARY_SHAPE: Shape = { syllables: [2, 3], letters: [6, 11] }
/** Each word of a Mythic's two-word name. */
const MYTHIC_WORD_SHAPE: Shape = { syllables: [2, 3], letters: [5, 11] }
