  const n = out.length
  const last = out[n - 1]
  if (last && last.s === 'e' && n >= 3 && !out[n - 2]!.v && out.slice(0, n - 2).some(u => u.v)) {
    const prev = out[n - 2]!.s
    const before = out[n - 3]!
    const syllabic = (prev === 'l' || prev === 'r') && !before.v && before.s !== 'r' && before.s !== 'l'
    if (!syllabic) last.silent = true
